package com.transportlogistics.app.system.infrastructure.adapters.out;
import com.transportlogistics.app.fleet.DriverPayrollSourcePort;import com.transportlogistics.app.trip.TripReportingQuery;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;
@Component class TripPayrollSourceAdapter implements DriverPayrollSourcePort{private final TripReportingQuery trips;TripPayrollSourceAdapter(TripReportingQuery t){trips=t;}public Optional<TripFact>trip(UUID driver,UUID trip,LocalDate start,LocalDate end){return trips.findDriverAssignments(start.atStartOfDay().atOffset(ZoneOffset.UTC),end.atStartOfDay().atOffset(ZoneOffset.UTC),driver).stream().filter(x->x.tripId().equals(trip)).map(x->new TripFact(x.tripId(),x.tripNumber(),x.status(),x.driverId(),x.actualEndTime())).findFirst();}}
